#include <bits/stdc++.h>
using namespace std;

int findNext(vector<int>& parent, int x) {
    int root = x;
    while (parent[root] != root) root = parent[root];
    while (parent[x] != x) {
        int next = parent[x];
        parent[x] = root;
        x = next;
    }
    return root;
}

int findPrev(vector<int>& parent, int x) {
    int root = x;
    while (parent[root] != root) root = parent[root];
    while (parent[x] != x) {
        int next = parent[x];
        parent[x] = root;
        x = next;
    }
    return root;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<long long> x(n), y(n), u(n), v(n);
    for (auto& a : x) cin >> a;
    for (auto& a : y) cin >> a;

    for (int i = 0; i < n; ++i) {
        u[i] = x[i] + y[i];
        v[i] = x[i] - y[i];
    }

    vector<int> orderU(n), orderV(n);
    iota(orderU.begin(), orderU.end(), 0);
    iota(orderV.begin(), orderV.end(), 0);

    sort(orderU.begin(), orderU.end(), [&](int a, int b) {
        return u[a] < u[b];
    });
    sort(orderV.begin(), orderV.end(), [&](int a, int b) {
        return v[a] < v[b];
    });

    vector<long long> valuesU(n), valuesV(n);
    vector<int> rankU(n), rankV(n);

    for (int i = 0; i < n; ++i) {
        valuesU[i] = u[orderU[i]];
        valuesV[i] = v[orderV[i]];
        rankU[orderU[i]] = i;
        rankV[orderV[i]] = i;
    }

    auto feasible = [&](long long d) -> bool {
        vector<int> loU(n), hiU(n), loV(n), hiV(n);

        int left = 0, right = 0;
        for (int i = 0; i < n; ++i) {
            while (valuesU[left] < valuesU[i] - d) ++left;
            if (right < i) right = i;
            while (right < n && valuesU[right] <= valuesU[i] + d) ++right;
            loU[i] = left;
            hiU[i] = right;
        }

        left = 0;
        right = 0;
        for (int i = 0; i < n; ++i) {
            while (valuesV[left] < valuesV[i] - d) ++left;
            if (right < i) right = i;
            while (right < n && valuesV[right] <= valuesV[i] + d) ++right;
            loV[i] = left;
            hiV[i] = right;
        }

        vector<int> nextU(n + 1), nextV(n + 1);
        vector<int> prevU(n + 1), prevV(n + 1);
        iota(nextU.begin(), nextU.end(), 0);
        iota(nextV.begin(), nextV.end(), 0);
        iota(prevU.begin(), prevU.end(), 0);
        iota(prevV.begin(), prevV.end(), 0);

        vector<int> color(n, -1);
        vector<int> queue;
        queue.reserve(n);

        long long minU[2] = {LLONG_MAX, LLONG_MAX};
        long long maxU[2] = {LLONG_MIN, LLONG_MIN};
        long long minV[2] = {LLONG_MAX, LLONG_MAX};
        long long maxV[2] = {LLONG_MIN, LLONG_MIN};

        auto addPoint = [&](int id, int c) {
            minU[c] = min(minU[c], u[id]);
            maxU[c] = max(maxU[c], u[id]);
            minV[c] = min(minV[c], v[id]);
            maxV[c] = max(maxV[c], v[id]);
        };

        auto removePoint = [&](int id) {
            int ru = rankU[id];
            int rv = rankV[id];
            nextU[ru] = findNext(nextU, ru + 1);
            prevU[ru + 1] = findPrev(prevU, ru);
            nextV[rv] = findNext(nextV, rv + 1);
            prevV[rv + 1] = findPrev(prevV, rv);
        };

        for (int start = 0; start < n; ++start) {
            if (color[start] != -1) continue;

            color[start] = 0;
            addPoint(start, 0);
            removePoint(start);
            queue.clear();
            queue.push_back(start);

            for (size_t head = 0; head < queue.size(); ++head) {
                int p = queue[head];
                int c = color[p];

                if (minU[c] < u[p] - d || maxU[c] > u[p] + d ||
                    minV[c] < v[p] - d || maxV[c] > v[p] + d) {
                    return false;
                }

                while (true) {
                    int id = -1;
                    int ru = rankU[p];
                    int rv = rankV[p];

                    int z = findPrev(prevU, loU[ru]);
                    if (z > 0) {
                        id = orderU[z - 1];
                    } else {
                        z = findNext(nextU, hiU[ru]);
                        if (z < n) {
                            id = orderU[z];
                        } else {
                            z = findPrev(prevV, loV[rv]);
                            if (z > 0) {
                                id = orderV[z - 1];
                            } else {
                                z = findNext(nextV, hiV[rv]);
                                if (z < n) id = orderV[z];
                            }
                        }
                    }

                    if (id == -1) break;

                    color[id] = 1 - c;
                    addPoint(id, 1 - c);
                    removePoint(id);
                    queue.push_back(id);
                }
            }
        }

        return true;
    };

    long long low = -1, high = 1'000'000'000LL;
    while (high - low > 1) {
        long long mid = (low + high) / 2;
        if (feasible(mid)) high = mid;
        else low = mid;
    }

    cout << high << '\n';
    return 0;
}
